_SHIFT_N = 1000
_DATA = None


def _load_data():
    """Decompresse (une fois) et verifie les donnees integrees."""
    global _DATA
    if _DATA is None:
        raw = zlib.decompress(base64.b64decode("".join(_B64.split())))
        if hashlib.sha256(raw).hexdigest() != _SHA256:
            raise RuntimeError("Donnees CEC2013 integrees corrompues (SHA-256 invalide).")
        a = np.frombuffer(raw, dtype="<f8").astype(np.float64)
        shift = a[:_SHIFT_N].copy()
        pos = _SHIFT_N
        mats = {}
        for d in DIMS:
            n = _CF_NUM * d * d
            mats[d] = a[pos:pos + n].reshape(_CF_NUM, d, d).copy()
            pos += n
        _DATA = (shift, mats)
    return _DATA


# ------------------------------------------------------------------ primitives
def _ssum(a):
    """Somme SEQUENTIELLE (comme la boucle for du C), pas la somme par paires de numpy."""
    return float(np.cumsum(a)[-1])


def _rot(M, v):
    """rotatefunc du C : xrot[i] = sum_j v[j]*M[i][j], accumulation sequentielle en j."""
    return np.cumsum(M * v, axis=1)[:, -1]


def _pow(a, b):
    """pow de la libm ; depassement -> inf comme en C (math.pow leve OverflowError)."""
    try:
        return math.pow(a, b)
    except OverflowError:
        return math.inf
    except ValueError:
        return math.nan


def _vpow(arr, p):
    return np.array([_pow(float(v), p) for v in arr])


def _exp(v):
    try:
        return math.exp(v)
    except OverflowError:
        return math.inf


def _sin(v):
    try:
        return math.sin(v)
    except ValueError:
        return math.nan


def _fmod(a, b):
    try:
        return math.fmod(a, b)
    except ValueError:
        return math.nan


def _osz(x):
    """oszfunc : seules les composantes 0 et nx-1 sont transformees."""
    out = x.copy()
    nx = x.size
    xx = 0.0
    for i in (0, nx - 1):
        xi = float(x[i])
        if xi != 0.0:
            xx = math.log(abs(xi))
        if xi > 0:
            c1, c2, sx = 10.0, 7.9, 1.0
        elif xi == 0:
            c1, c2, sx = 5.5, 3.1, 0.0
        else:
            c1, c2, sx = 5.5, 3.1, -1.0
        out[i] = sx * _exp(xx + 0.049 * (_sin(c1 * xx) + _sin(c2 * xx)))
    return out


# ------------------------------------------------------------------ evaluateur
class CEC2013:
    """Fonction CEC2013 numero `func_num` (1..28) en dimension `dim` (10, 30 ou 50)."""

    def __init__(self, func_num, dim=30, data_dir=None):
        # data_dir : conserve pour compatibilite avec l'ancienne API, IGNORE
        # (les donnees sont integrees a ce fichier).
        func_num, dim = int(func_num), int(dim)
        if func_num not in F_BIAS:
            raise ValueError("func_num doit etre dans 1..28")
        shift, mats = _load_data()
        if dim not in mats:
            raise ValueError("Dimension %d non integree ; disponibles : %s" % (dim, DIMS))
        self.func_num = func_num
        self.dim = self.nx = dim
        self.name = NAMES[func_num]
        self.type = TYPES[func_num]
        self.Ms = mats[dim]                                   # (10, dim, dim)
        self.OShift = (shift[:dim] if func_num < 21 else shift[:_CF_NUM * dim]).copy()
        self.f_opt = self.f_global = F_BIAS[func_num]
        self.x_opt = self.x_global = (self.OShift.copy() if func_num < 21
                                      else self.OShift[:dim].copy())
        self.lb = LB * np.ones(dim)
        self.ub = UB * np.ones(dim)

        # constantes (calculees avec pow/sqrt de la libm, comme le C)
        n1 = dim - 1
        self._pw = np.array([math.pow(10.0, 1.0 * i / n1 / 2.0) for i in range(dim)])
        self._pw100 = np.array([math.pow(100.0, 1.0 * i / n1 / 2.0) for i in range(dim)])
        self._ell = np.array([math.pow(10.0, 6.0 * i / n1) for i in range(dim)])
        self._expo = [2 + (4 * i) // n1 for i in range(dim)]  # division ENTIERE du C
        self._gdiv = np.array([math.sqrt(1.0 + i) for i in range(dim)])
        a = np.array([math.pow(0.5, j) for j in range(21)])
        self._wk_a = a
        self._wk_k = np.array([2.0 * PI * math.pow(3.0, j) for j in range(21)])
        self._wk_sum2 = _ssum(a * np.cos(self._wk_k * 0.5))
        self._kt_p2 = np.array([math.pow(2.0, j) for j in range(1, 33)])
        self._kt_e = 10.0 / math.pow(1.0 * dim, 1.2)

    # ------------------------------------------------------------- utilitaires
    def _asy(self, x, xasy, beta):
        """asyfunc : xasy[i] n'est ecrit que si x[i] > 0 (sinon ancienne valeur)."""
        n1 = self.nx - 1
        for i in np.flatnonzero(x > 0):
            i = int(i)
            xi = float(x[i])
            xasy[i] = _pow(xi, 1.0 + beta * i / n1 * _pow(xi, 0.5))

    # ------------------------------------------------------ fonctions de base
    # Signature : f(x, Os, Mr, r) ; Mr[0] = matrice courante, Mr[1] = suivante
    # (&Mr[nx*nx] du C) ; r = r_flag du C.
    def sphere(self, x, Os, Mr, r):
        y = x - Os
        z = _rot(Mr[0], y) if r else y
        return _ssum(z * z)

    def ellips(self, x, Os, Mr, r):
        y = x - Os
        z = _rot(Mr[0], y) if r else y
        y = _osz(z)
        return _ssum(self._ell * y * y)

    def bent_cigar(self, x, Os, Mr, r):
        y = x - Os
        z = _rot(Mr[0], y) if r else y.copy()
        self._asy(z, y, 0.5)
        z = _rot(Mr[1], y) if r else y.copy()
        t = 1.0e6 * z * z
        t[0] = z[0] * z[0]
        return _ssum(t)

    def discus(self, x, Os, Mr, r):
        y = x - Os
        z = _rot(Mr[0], y) if r else y
        y = _osz(z)
        t = y * y
        t[0] = 1.0e6 * y[0] * y[0]
        return _ssum(t)

    def dif_powers(self, x, Os, Mr, r):
        y = x - Os
        z = _rot(Mr[0], y) if r else y
        s = _ssum(np.array([_pow(abs(float(v)), e) for v, e in zip(z, self._expo)]))
        return _pow(s, 0.5)

    def rosenbrock(self, x, Os, Mr, r):
        y = (x - Os) * 2.048 / 100.0
        z = _rot(Mr[0], y) if r else y
        z = z + 1.0
        t1 = z[:-1] * z[:-1] - z[1:]
        t2 = z[:-1] - 1.0
        return _ssum(100.0 * t1 * t1 + t2 * t2)

    def schaffer_F7(self, x, Os, Mr, r):
        nx = self.nx
        y = x - Os
        z = _rot(Mr[0], y) if r else y.copy()
        self._asy(z, y, 0.5)
        z = y * self._pw
        y = _rot(Mr[1], z) if r else z
        zz = _vpow(y[:-1] * y[:-1] + y[1:] * y[1:], 0.5)
        tmp = np.sin(50.0 * _vpow(zz, 0.2))
        sq = _vpow(zz, 0.5)
        f = _ssum(sq + sq * tmp * tmp)
        return f * f / (nx - 1) / (nx - 1)

    def ackley(self, x, Os, Mr, r):
        nx = self.nx
        y = x - Os
        z = _rot(Mr[0], y) if r else y.copy()
        self._asy(z, y, 0.5)
        z = y * self._pw
        y = _rot(Mr[1], z) if r else z
        sum1 = _ssum(y * y)
        sum2 = _ssum(np.cos(2.0 * PI * y))
        sum1 = -0.2 * math.sqrt(sum1 / nx)
        sum2 /= nx
        return E - 20.0 * _exp(sum1) - _exp(sum2) + 20.0

    def weierstrass(self, x, Os, Mr, r):
        nx = self.nx
        y = (x - Os) * 0.5 / 100.0
        z = _rot(Mr[0], y) if r else y.copy()
        self._asy(z, y, 0.5)
        z = y * self._pw
        y = _rot(Mr[1], z) if r else z
        terms = self._wk_a[None, :] * np.cos(self._wk_k[None, :] * (y[:, None] + 0.5))
        f = _ssum(np.cumsum(terms, axis=1)[:, -1])
        return f - nx * self._wk_sum2

    def griewank(self, x, Os, Mr, r):
        y = (x - Os) * 600.0 / 100.0
        z = _rot(Mr[0], y) if r else y
        z = z * self._pw100
        s = _ssum(z * z)
        p = float(np.cumprod(np.cos(z / self._gdiv))[-1])
        return 1.0 + s / 4000.0 - p

    def _rastrigin_core(self, x, Os, Mr, r, step):
        nx = self.nx
        y = (x - Os) * 5.12 / 100.0
        z = _rot(Mr[0], y) if r else y.copy()
        if step:                                   # F13 : arrondi par pas de 0.5
            m = np.abs(z) > 0.5
            z[m] = np.floor(2 * z[m] + 0.5) / 2
        y = _osz(z)
        self._asy(y, z, 0.2)                       # z[i] garde sa valeur si y[i] <= 0
        y = _rot(Mr[1], z) if r else z.copy()
        y = y * self._pw
        z = _rot(Mr[0], y) if r else y
        return _ssum(z * z - 10.0 * np.cos(2.0 * PI * z) + 10.0)

    def rastrigin(self, x, Os, Mr, r):
        return self._rastrigin_core(x, Os, Mr, r, False)

    def step_rastrigin(self, x, Os, Mr, r):
        return self._rastrigin_core(x, Os, Mr, r, True)

    def schwefel(self, x, Os, Mr, r):
        nx = self.nx
        y = (x - Os) * 10.0                        # y *= 1000/100 (division entiere C = 10)
        z = _rot(Mr[0], y) if r else y
        y = z * self._pw
        z = y + 4.209687462275036e+002
        if np.all(np.abs(z) <= 500.0):             # cas courant : tout dans [-500, 500]
            f = -_ssum(z * np.sin(_vpow(np.abs(z), 0.5)))
        else:                                      # branches |z| > 500 : boucle comme le C
            f = 0.0
            for v in z:
                v = float(v)
                if v > 500.0:
                    m = _fmod(v, 500.0)
                    f -= (500.0 - m) * _sin(_pow(500.0 - m, 0.5))
                    t = (v - 500.0) / 100.0
                    f += t * t / nx
                elif v < -500.0:
                    m = _fmod(abs(v), 500.0)
                    f -= (-500.0 + m) * _sin(_pow(500.0 - m, 0.5))
                    t = (v + 500.0) / 100.0
                    f += t * t / nx
                else:
                    f -= v * _sin(_pow(abs(v), 0.5))
        return 4.189828872724338e+002 * nx + f

    def katsuura(self, x, Os, Mr, r):
        nx = self.nx
        y = (x - Os) * (5.0 / 100.0)
        z = _rot(Mr[0], y) if r else y
        z = z * self._pw100
        y = _rot(Mr[1], z) if r else z
        p2 = self._kt_p2[None, :]
        t = p2 * y[:, None]
        temp = np.cumsum(np.abs(t - np.floor(t + 0.5)) / p2, axis=1)[:, -1]
        terms = np.array([_pow(1.0 + (i + 1) * float(temp[i]), self._kt_e)
                          for i in range(nx)])
        f = float(np.cumprod(terms)[-1])
        tmp1 = 10.0 / nx / nx
        return f * tmp1 - tmp1

    def bi_rastrigin(self, x, Os, Mr, r):
        nx = self.nx
        mu0, d = 2.5, 1.0
        s = 1.0 - 1.0 / (2.0 * _pow(nx + 20.0, 0.5) - 8.2)
        mu1 = -_pow((mu0 * mu0 - d) / s, 0.5)
        y = (x - Os) * (10.0 / 100.0)
        tmpx = 2 * y
        tmpx = np.where(Os < 0.0, -tmpx, tmpx)
        z = tmpx.copy()
        tmpx = tmpx + mu0
        y = _rot(Mr[0], z) if r else z.copy()
        y = y * self._pw100
        z = _rot(Mr[1], y) if r else y
        tmp1 = _ssum((tmpx - mu0) * (tmpx - mu0))
        tmp2 = _ssum((tmpx - mu1) * (tmpx - mu1))
        tmp2 *= s
        tmp2 += d * nx
        tmp = _ssum(np.cos(2.0 * PI * z))
        f = tmp1 if tmp1 < tmp2 else tmp2
        return f + 10.0 * (nx - tmp)

    def grie_rosen(self, x, Os, Mr, r):
        # Code officiel : z = 5(x-o)/100 + 1 ; la rotation calculee par le C est ecrasee.
        y = (x - Os) * 5.0 / 100.0
        z = y + 1.0
        zn = np.roll(z, -1)                        # z[i+1], et z[0] pour i = nx-1
        t1 = z * z - zn
        t2 = z - 1.0
        temp = 100.0 * t1 * t1 + t2 * t2
        return _ssum((temp * temp) / 4000.0 - np.cos(temp) + 1.0)

    def escaffer6(self, x, Os, Mr, r):
        y = x - Os
        z = _rot(Mr[0], y) if r else y.copy()
        self._asy(z, y, 0.5)
        z = _rot(Mr[1], y) if r else y
        zn = np.roll(z, -1)
        s2 = z * z + zn * zn
        sn = np.sin(np.sqrt(s2))
        t1 = sn * sn
        t2 = 1.0 + 0.001 * s2
        return _ssum(0.5 + (t1 - 0.5) / (t2 * t2))

    # ------------------------------------------------------------ compositions
    def _cf_cal(self, x, Os, delta, bias, fit):
        nx = self.nx
        n = len(fit)
        fit = [fit[i] + bias[i] for i in range(n)]
        w = [0.0] * n
        w_max = 0.0
        for i in range(n):
            d = x - Os[i * nx:(i + 1) * nx]
            s = _ssum(d * d)                       # pow(.,2.0) : le compilateur C le remplace par d*d
            if s != 0.0:
                w[i] = _pow(1.0 / s, 0.5) * _exp(-s / 2.0 / nx / (float(delta[i]) * float(delta[i])))
            else:
                w[i] = INF
            if w[i] > w_max:
                w_max = w[i]
        w_sum = 0.0
        for i in range(n):
            w_sum = w_sum + w[i]
        if w_max == 0:
            w = [1.0] * n
            w_sum = float(n)
        f = 0.0
        for i in range(n):
            f = f + w[i] / w_sum * fit[i]
        return f

    def _comp(self, x, Os, Ms, r, spec, delta, bias):
        """spec = [(methode, rotation utilisee ?, num, denom), ...] ; composante i : Os[i*nx:], Ms[i:]."""
        nx = self.nx
        fit = []
        for i, (fn, rot, num, den) in enumerate(spec):
            v = fn(x, Os[i * nx:(i + 1) * nx], Ms[i:], r if rot else 0)
            if num is not None:
                v = num * v / den
            fit.append(v)
        return self._cf_cal(x, Os, delta, bias, fit)

    def cf01(self, x, Os, Ms, r):
        spec = [(self.rosenbrock, 1, 10000.0, 1e4), (self.dif_powers, 1, 10000.0, 1e10),
                (self.bent_cigar, 1, 10000.0, 1e30), (self.discus, 1, 10000.0, 1e10),
                (self.sphere, 0, 10000.0, 1e5)]
        return self._comp(x, Os, Ms, r, spec, [10, 20, 30, 40, 50], [0, 100, 200, 300, 400])

    def cf02(self, x, Os, Ms, r):
        spec = [(self.schwefel, 1, None, None)] * 3
        return self._comp(x, Os, Ms, r, spec, [20, 20, 20], [0, 100, 200])

    def cf03(self, x, Os, Ms, r):
        spec = [(self.schwefel, 1, None, None)] * 3
        return self._comp(x, Os, Ms, r, spec, [20, 20, 20], [0, 100, 200])

    def cf04(self, x, Os, Ms, r):
        spec = [(self.schwefel, 1, 1000.0, 4e3), (self.rastrigin, 1, 1000.0, 1e3),
                (self.weierstrass, 1, 1000.0, 400.0)]
        return self._comp(x, Os, Ms, r, spec, [20, 20, 20], [0, 100, 200])

    def cf05(self, x, Os, Ms, r):
        spec = [(self.schwefel, 1, 1000.0, 4e3), (self.rastrigin, 1, 1000.0, 1e3),
                (self.weierstrass, 1, 1000.0, 400.0)]
        return self._comp(x, Os, Ms, r, spec, [10, 30, 50], [0, 100, 200])

    def cf06(self, x, Os, Ms, r):
        spec = [(self.schwefel, 1, 1000.0, 4e3), (self.rastrigin, 1, 1000.0, 1e3),
                (self.ellips, 1, 1000.0, 1e10), (self.weierstrass, 1, 1000.0, 400.0),
                (self.griewank, 1, 1000.0, 100.0)]
        return self._comp(x, Os, Ms, r, spec, [10, 10, 10, 10, 10], [0, 100, 200, 300, 400])

    def cf07(self, x, Os, Ms, r):
        spec = [(self.griewank, 1, 10000.0, 100.0), (self.rastrigin, 1, 10000.0, 1e3),
                (self.schwefel, 1, 10000.0, 4e3), (self.weierstrass, 1, 10000.0, 400.0),
                (self.sphere, 0, 10000.0, 1e5)]
        return self._comp(x, Os, Ms, r, spec, [10, 10, 10, 20, 20], [0, 100, 200, 300, 400])

    def cf08(self, x, Os, Ms, r):
        spec = [(self.grie_rosen, 1, 10000.0, 4e3), (self.schaffer_F7, 1, 10000.0, 4e6),
                (self.schwefel, 1, 10000.0, 4e3), (self.escaffer6, 1, 10000.0, 2e7),
                (self.sphere, 0, 10000.0, 1e5)]
        return self._comp(x, Os, Ms, r, spec, [10, 20, 30, 40, 50], [0, 100, 200, 300, 400])

    # ------------------------------------------------------------------ appel
    def _eval(self, x):
        k, O, Ms = self.func_num, self.OShift, self.Ms
        if k == 1:    v = self.sphere(x, O, Ms, 0)
        elif k == 2:  v = self.ellips(x, O, Ms, 1)
        elif k == 3:  v = self.bent_cigar(x, O, Ms, 1)
        elif k == 4:  v = self.discus(x, O, Ms, 1)
        elif k == 5:  v = self.dif_powers(x, O, Ms, 0)
        elif k == 6:  v = self.rosenbrock(x, O, Ms, 1)
        elif k == 7:  v = self.schaffer_F7(x, O, Ms, 1)
        elif k == 8:  v = self.ackley(x, O, Ms, 1)
        elif k == 9:  v = self.weierstrass(x, O, Ms, 1)
        elif k == 10: v = self.griewank(x, O, Ms, 1)
        elif k == 11: v = self.rastrigin(x, O, Ms, 0)
        elif k == 12: v = self.rastrigin(x, O, Ms, 1)
        elif k == 13: v = self.step_rastrigin(x, O, Ms, 1)
        elif k == 14: v = self.schwefel(x, O, Ms, 0)
        elif k == 15: v = self.schwefel(x, O, Ms, 1)
        elif k == 16: v = self.katsuura(x, O, Ms, 1)
        elif k == 17: v = self.bi_rastrigin(x, O, Ms, 0)
        elif k == 18: v = self.bi_rastrigin(x, O, Ms, 1)
        elif k == 19: v = self.grie_rosen(x, O, Ms, 1)
        elif k == 20: v = self.escaffer6(x, O, Ms, 1)
        elif k == 21: v = self.cf01(x, O, Ms, 1)
        elif k == 22: v = self.cf02(x, O, Ms, 0)
        elif k == 23: v = self.cf03(x, O, Ms, 1)
        elif k == 24: v = self.cf04(x, O, Ms, 1)
        elif k == 25: v = self.cf05(x, O, Ms, 1)
        elif k == 26: v = self.cf06(x, O, Ms, 1)
        elif k == 27: v = self.cf07(x, O, Ms, 1)
        else:         v = self.cf08(x, O, Ms, 1)
        return float(v) + F_BIAS[k]

    def __call__(self, x):
        a = np.asarray(x, dtype=float)
        with np.errstate(all="ignore"):
            if a.ndim == 1 and a.size == self.nx:
                return self._eval(a)
            if a.ndim == 2 and a.shape[1] == self.nx:
                return np.array([self._eval(row) for row in a])
        raise ValueError("x doit etre de forme (%d,) ou (n, %d)" % (self.nx, self.nx))

    evaluate = __call__

    def error(self, x):
        """Erreur CEC = f(x) - f_opt ; toute valeur absolue < 1e-8 est ramenee a 0."""
        e = np.asarray(self(x) - self.f_opt)
        e = np.where(np.abs(e) < 1e-8, 0.0, e)
        return float(e) if e.ndim == 0 else e


# --------------------------------------------------- interface
def get_function(fid, dim, data_dir=None):
    return CEC2013(fid, dim, data_dir)


def get_all_functions(dim, ids=None, data_dir=None):
    ids = FUNC_IDS if ids is None else ids
    return {i: get_function(i, dim, data_dir) for i in ids}


def make_objective(fid, dim, data_dir=None):
    """Retourne (objectif, lb, ub, f_opt) ; objectif(x) -> float."""
    f = get_function(fid, dim, data_dir)
    return (lambda x: float(f(np.asarray(x, dtype=float)))), f.lb, f.ub, f.f_global


def max_fes(dim):
    return MAX_FES_FACTOR * dim
